#!/usr/bin/env bash
# NOTE: THIS SOURCE FILE WAS GENERATED BY CLAUDE OPUS 4.8 WITH LITTLE HUMAN OVERSIGHT
# PLEASE REVIEW THE AI POLICY AT REPOSITORY ROOT FOR MORE INFORMATION
# Regenerate the concatenated EXAMPLE bundles the tutor fetches: tutorial.txt plus one
# bundle per gallery topic, every source file preceded by a "=== FILE: <package>:<path>"
# header (matching the refs in examples_index.md). Grouping comes from the docs gallery
# (docs/examples.yaml via regenerate_index.build_gallery), so a cross-listed example
# appears in every topic it's listed under. Also regenerates and copies the index.
#
# Must run inside the scamp-meta workspace. Requires scamp + PyYAML importable.
# The output under scamp_tutor/tutor/examples/ is committed on purpose — it's what the tutor
# fetches over the web, not a throwaway build product. Don't gitignore it.
#
# Run from anywhere: ./regenerate_bundles.sh
set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
repo="$(cd "$here/../../.." && pwd)"
site="$repo/scamp_tutor/tutor"   # what the tutor reads and Pages serves
out="$site/examples"

python3 "$repo/docs/regenerate_index.py"
rm -rf "$out"
mkdir -p "$out"

python3 - "$repo/docs" "$out" <<'PY'
import sys, pathlib
sys.path.insert(0, sys.argv[1])
from regenerate_index import build_gallery, slugify, PACKAGES
out = pathlib.Path(sys.argv[2])
bar = '=' * 70

def sources(u):
    # .py plus SuperCollider companions, so folder examples come through whole
    if not u['is_folder']:
        return [u['path']]
    return sorted(p for p in u['path'].rglob('*')
                  if p.suffix in ('.py', '.scd') and '__pycache__' not in p.parts)

def write_bundle(name, units):
    seen, n = set(), 0
    with (out / f'{name}.txt').open('w') as fo:
        for u in units:
            if u['key'] in seen:
                continue
            seen.add(u['key'])
            for f in sources(u):
                rel = f.relative_to(PACKAGES[u['package']]).as_posix()
                fo.write(f'\n\n{bar}\n=== FILE: {u["package"]}:{rel}\n{bar}\n\n')
                fo.write(f.read_text())
                n += 1
    print(f'examples/{name}.txt -> {n} files')

g = build_gallery()
write_bundle('tutorial', g['tutorial'])
for topic, sections in g['topics'].items():
    write_bundle(slugify(topic), [u for us in sections.values() for u in us])
PY

cp "$repo/docs/INDEX.md" "$out/examples_index.md"
echo "examples/examples_index.md <- docs/INDEX.md"

python3 "$here/build_html.py"
